local ECSComponent = import("Frame.ECS.ECSComponent")
---@class CustomTrainComponent
local CustomTrainComponent = Class("CustomTrainComponent", ECSComponent)
---@type CustomTrainDojo
local CustomTrainDojo = import("Game.Dojo.CustomTrainDojo")
function CustomTrainComponent:__init()
    ECSComponent.__init(self)
end

function CustomTrainComponent:__delete()
    self.customTrainDojo = nil
end

function CustomTrainComponent:FillData(jsonStr)
    local datas = nil
    if type(jsonStr) == 'string' then
        datas = table.deserialize(jsonStr)
    else
        datas = checkTable(jsonStr)
    end
    ---@type PlayerComponent
    local PlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local currentTime = PlayerComponent:GetPlayerDojo():GetServerTime()
    datas.rewardResetLeftSeconds =  currentTime + datas.rewardResetLeftSeconds
    datas.statusLeftSeconds =  currentTime + checkInt(datas.statusLeftSeconds)
    self.customTrainDojo = CustomTrainDojo.New()
    self.customTrainDojo:Fill(datas)
end
---@return CustomTrainDojo
function CustomTrainComponent:GetDojo()
    return self.customTrainDojo
end
---@return CustomTrainPersonHurtVo[]
function CustomTrainComponent:GetPersonHurtPointVoByRewardGroupId(rewardGroupId)
    rewardGroupId = tostring(rewardGroupId)
    local  CustomTrainPersonHurtVos = {}
    ---@type CustomTrainPersonHurtVo[]
    local CustomTrainPersonHurtVoArray = CfUtils.GetWholeVo(AutoIds.IdSetting8944 , "CustomTrainPersonHurtVo")
    for voIndex, CustomTrainPersonHurtVo in ipairs(CustomTrainPersonHurtVoArray) do
        local rewardGroup = tostring(CustomTrainPersonHurtVo.rewardGroup)
        if not CustomTrainPersonHurtVos[rewardGroup] then
            CustomTrainPersonHurtVos[rewardGroup] = {} 
        end
        local data = CustomTrainPersonHurtVos[rewardGroup]
        data[#data+1] = CustomTrainPersonHurtVo
    end     
    return CustomTrainPersonHurtVos[rewardGroupId]
end

--- func desc 更具区域获取奖励
---@param areaId any
function CustomTrainComponent:GetRewardsByRewardGroupArea(rewardGroupId,areaId)
    local damages =  self:GetDojo().damages or {}
    local hurtPoint = checkInt(damages[tostring(areaId)]) 
    if hurtPoint > 0 then    
        -- -- ---@type CustomTrainQuestVo
        -- local CustomTrainQuestVo = CfUtils.GetCfVo(AutoIds.IdSetting8945 ,"CustomTrainQuestVo",  areaId)
        -- local rewardGroup = CustomTrainQuestVo.rewardGroup
        local CustomTrainPersonHurtVos = self:GetPersonHurtPointVoByRewardGroupId(rewardGroupId)
        for i = #CustomTrainPersonHurtVos , 1, -1 do
            local CustomTrainPersonHurtVo = CustomTrainPersonHurtVos[i]
            if hurtPoint >= CustomTrainPersonHurtVo.upperLimit then
                return CustomTrainPersonHurtVo.rewards
            end
        end
    end
    return nil
end

--- func desc  通过关卡获取questVos
---@param groupId  当前的组 groupId
---@return CustomTrainQuestVo[]
function CustomTrainComponent:GetCustomTrainQuestVosByGroupId(groupId)
    local groupId = checkInt(groupId)
    ---@type CustomTrainQuestVo[]
    local CustomTrainQuestVos = CfUtils.GetWholeVo(AutoIds.IdSetting8945 ,"CustomTrainQuestVo")
    ---@type CustomTrainQuestVo[]
    local questVos = {}
    for i, v in ipairs(CustomTrainQuestVos) do
        if v.groupId == groupId then
            questVos[#questVos+1] = v
        end
    end
    table.sort(questVos , function (a , b)
        return checkInt(a.areaId) < checkInt(b.areaId)
    end)
    return questVos
end

--- func desc  通过关卡获取questVos
---@param groupId  当前的组 groupId
---@return CustomTrainLineUpVo[]
function CustomTrainComponent:GetCustomTrainLineUpByQuestId(questId)
    local questId = checkInt(questId)
    ---@type CustomTrainLineUpVo[]
    local CustomTrainLineUpVos = CfUtils.GetWholeVo(AutoIds.IdSetting8946 ,"CustomTrainLineUpVo")
    ---@type CustomTrainQuestVo[]
    local lineUpVo = nil
    for i, v in ipairs(CustomTrainLineUpVos) do
        if v.id == questId then
            lineUpVo = v 
            break
        end
    end
    return lineUpVo
end

return CustomTrainComponent